// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {EtherCartel} from "../src/EtherCartel.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    EtherCartel c;

    function setUp() public {
        c = new EtherCartel();
    }

    function _test(address newCEO) internal {
        vm.assume(newCEO != 0x85abE8E3bed0d4891ba201Af1e212FE50bb65a26);
        address oldCEO;
        try c.ceoAddress() returns (address __r) { oldCEO = __r; } catch { return; }
        try c.DrugDealer() {} catch { return; }
        assertTrue(c.ceoAddress() == oldCEO);
    }

    function testFuzz_test(address newCEO) public {
        _test(newCEO);
    }

    receive() external payable {}
}
